function h({registerIndicator:f,sourceValues:m,nulls:y}){f({id:"oa-dpo",name:"Detrended Price Oscillator (DPO)",category:"Oscillators",placement:"pane",inputs:[{key:"source",type:"source",label:"Source",default:"close"},{key:"period",type:"number",label:"Period",default:20,min:1,max:5e3,step:1}],plots:[{key:"dpo",type:"line",title:"DPO",style:{color:"#ffeb3b",lineWidth:2}}],levels:()=>[{price:0,title:"Zero Line",color:"#787b86",lineStyle:"dotted"}],calc(s,a){const n=Math.max(1,Math.floor(Number(a.period)||20)),l=m(s,a.source??"close"),o=s.length,d=Math.floor(n/2)+1,r=new Array(o+1).fill(0),c=new Array(o+1).fill(0);for(let e=0;e<o;e++){const t=Number.isFinite(l[e]);r[e+1]=r[e]+(t?l[e]:0),c[e+1]=c[e]+(t?0:1)}const p=new Array(o).fill(NaN);for(let e=0;e<o;e++){const t=l[e];if(!Number.isFinite(t))continue;const i=Math.max(0,e-n+1),b=e-i+1,N=n-b+(c[e+1]-c[i]);p[e]=(r[e+1]-r[i]+N*t)/n}const u=new Array(o).fill(NaN);for(let e=d;e<o;e++){const t=l[e],i=p[e-d];!Number.isFinite(t)||!Number.isFinite(i)||(u[e]=t-i)}return{dpo:y(u)}}})}export{h as default};
